Function siguiente <- MasUno(x As Integer)
  Define siguiente As Integer;
  siguiente <- x + 1;
EndFunction

Function barato <- EsBarato(precio As Integer)
  Define barato As Boolean;
  barato <- precio <= 2;
EndFunction

Function total <- Sumar(a As Integer, b As Integer)
  Define total As Integer;
  total <- a + b;
EndFunction

Function nuevos <- Mapear(v As Vector<Integer>, f As Function(Integer) As Integer)
  Define nuevos As Vector<Integer> <- vector();
  For Each elemento In v Do
    nuevos.append(f(elemento));
  EndFor
EndFunction

Function elegidos <- Filtrar(v As Vector<Integer>, condicion As Function(Integer) As Boolean)
  Define elegidos As Vector<Integer> <- vector();
  For Each elemento In v Do
    If condicion(elemento) Then
      elegidos.append(elemento);
    EndIf
  EndFor
EndFunction

Function acumulado <- Reducir(v As Vector<Integer>, f As Function(Integer, Integer) As Integer, inicial As Integer)
  Define acumulado As Integer <- inicial;
  For Each elemento In v Do
    acumulado <- f(acumulado, elemento);
  EndFor
EndFunction

Algorithm Precios
  Define precios As Vector<Integer> <- vector();
  precios.append(3);
  precios.append(5);
  precios.append(2);
  precios.append(1);
  precios.append(2);
  Write Mapear(precios, MasUno);
  Write Filtrar(precios, EsBarato);
  Write Reducir(precios, Sumar, 0);
EndAlgorithm
